from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import HandleInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message


def _adf_to_text(node: Any) -> str:
    """Flatten an Atlassian Document Format (ADF) node into plain text."""
    if node is None:
        return ""
    if isinstance(node, str):
        return node
    if isinstance(node, list):
        return "\n".join(part for part in (_adf_to_text(item) for item in node) if part)
    if not isinstance(node, dict):
        return str(node)
    if isinstance(node.get("text"), str):
        return node["text"]
    parts = [part for part in (_adf_to_text(child) for child in node.get("content", [])) if part]
    joiner = "\n" if node.get("type") in {"paragraph", "heading", "listItem"} else ""
    return joiner.join(parts)


class JiraIssueFields(Component):
    display_name = "Jira Issue Fields"
    description = "Extract issue key, summary, description, status and priority from a Jira issue API response."
    documentation = "https://developer.atlassian.com/cloud/jira/platform/rest/v3/api-group-issues/"
    icon = "ticket"
    name = "JiraIssueFields"

    inputs = [
        HandleInput(
            name="issue_data",
            display_name="Jira Issue",
            input_types=["Data", "JSON", "DataFrame"],
            info="Response from the Jira issue API Request component.",
            required=True,
        ),
    ]

    outputs = [
        Output(display_name="Issue Key", name="issue_key", method="extract_issue_key"),
        Output(display_name="Summary", name="summary", method="extract_summary"),
        Output(display_name="Description", name="description", method="extract_description"),
        Output(display_name="Status", name="issue_status", method="extract_status"),
        Output(display_name="Priority", name="priority", method="extract_priority"),
    ]

    def _payload(self) -> dict:
        data = self.issue_data
        if isinstance(data, Data):
            data = data.data
        if isinstance(data, list) and data:
            data = data[0]
        payload = data if isinstance(data, dict) else {}
        wrapper = payload.get("data")
        if isinstance(wrapper, dict):
            payload = wrapper
        issue = payload.get("result")
        if isinstance(issue, dict):
            payload = issue
        return payload

    def _fields(self) -> dict:
        fields = self._payload().get("fields")
        return fields if isinstance(fields, dict) else {}

    def extract_issue_key(self) -> Message:
        return Message(text=str(self._payload().get("key", "")))

    def extract_summary(self) -> Message:
        return Message(text=str(self._fields().get("summary", "")))

    def extract_description(self) -> Message:
        return Message(text=_adf_to_text(self._fields().get("description")))

    def extract_status(self) -> Message:
        status = self._fields().get("status")
        return Message(text=str(status.get("name", "")) if isinstance(status, dict) else str(status or ""))

    def extract_priority(self) -> Message:
        priority = self._fields().get("priority")
        return Message(text=str(priority.get("name", "")) if isinstance(priority, dict) else str(priority or ""))
